package br.com.brindespro.catalog;
import jakarta.persistence.*;import java.util.*;
@Entity @Table(name="products") public class Product { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) public Long id; @Column(nullable=false) public String name; @Column(nullable=false,unique=true) public String slug; @Column(length=2000) public String description=""; @ManyToOne(optional=false) @JoinColumn(name="category_id") public Category category; @Column(name="image_url") public String imageUrl; @Column(nullable=false) public boolean active=true; @Column(name="min_quantity") public int minQuantity=5; @OneToMany(mappedBy="product",cascade=CascadeType.ALL,orphanRemoval=true,fetch=FetchType.EAGER) @OrderBy("id ASC") public Set<ProductVariant> variants=new LinkedHashSet<>(); @OneToMany(mappedBy="product",cascade=CascadeType.ALL,orphanRemoval=true,fetch=FetchType.EAGER) @OrderBy("minQuantity ASC") public Set<PricingTier> tiers=new LinkedHashSet<>(); @OneToMany(mappedBy="product",cascade=CascadeType.ALL,orphanRemoval=true,fetch=FetchType.EAGER) @OrderBy("sortOrder ASC") public Set<ProductImage> images=new LinkedHashSet<>(); @Column(name="engraving_options") public String engravingOptions="Laser"; protected Product(){} public Product(String name,String slug,Category category,String imageUrl){this.name=name;this.slug=slug;this.category=category;this.imageUrl=imageUrl;} }
